from PIL import Image
from collections import deque

def analyze(fn, lo=(160,145,125), hi=(225,210,185)):
    im=Image.open(fn).convert('RGB')
    W,H=im.size
    # downsample by 2 for speed
    step=2
    w=W//step; h=H//step
    mask=[[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b=im.getpixel((x*step,y*step))
            if lo[0]<=r<=hi[0] and lo[1]<=g<=hi[1] and lo[2]<=b<=hi[2]:
                mask[y][x]=True
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for y in range(h):
        for x in range(w):
            if mask[y][x] and not seen[y][x]:
                q=deque([(x,y)]); seen[y][x]=True; n=0; minx=x; maxx=x; miny=y; maxy=y
                while q:
                    cx,cy=q.popleft(); n+=1
                    if cx<minx:minx=cx
                    if cx>maxx:maxx=cx
                    if cy<miny:miny=cy
                    if cy>maxy:maxy=cy
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=cx+dx,cy+dy
                        if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((nx,ny))
                comps.append((n,minx*step,miny*step,maxx*step+step-1,maxy*step+step-1))
    comps.sort(reverse=True)
    print('\n===',fn,'threshold',lo,hi,'components',len(comps))
    for c in comps[:15]:
        n,x0,y0,x1,y1=c
        print(f'n={n:6d} bbox=({x0},{y0})-({x1},{y1}) size={x1-x0+1}x{y1-y0+1}')

for fn in ['/home/robot/captures/carton_005.jpg','/home/robot/captures/overview_004.jpg']:
    analyze(fn, (150,135,110),(230,215,190))
    analyze(fn, (160,145,120),(220,205,180))
    analyze(fn, (170,155,130),(210,195,170))
